"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import type { Lectie } from "../data/lectii";
import { createClient } from "../lib/supabase/client";

type Props = {
  lectie: Lectie;
};

export default function LectieUniversala({ lectie }: Props) {
  const router = useRouter();
  const [supabase] = useState(() => createClient());

  const [accesVerificat, setAccesVerificat] =
    useState(false);

  const [exercitiuCurent, setExercitiuCurent] =
    useState(0);

  const [raspuns, setRaspuns] =
    useState<number | null>(null);

  const [verificat, setVerificat] =
    useState(false);

  const [xpLectie, setXpLectie] =
    useState(0);

  const [lectieFinalizata, setLectieFinalizata] =
    useState(false);

  const [videoDeschis, setVideoDeschis] =
    useState<number | null>(null);

  const [salvareCloud, setSalvareCloud] = useState<
    "nimic" | "salvare" | "salvat" | "eroare"
  >("nimic");

  useEffect(() => {
    let activ = true;

    async function verificaAccesulSiIncarcaProgresul() {
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (!activ) {
        return;
      }

      if (userError || !user) {
        router.replace("/cont");
        return;
      }

      const { data: profil, error: profilError } =
        await supabase
          .from("profiles")
          .select(
            "nume, profil_bac, evaluare_initiala_finalizata"
          )
          .eq("id", user.id)
          .maybeSingle();

      if (!activ) {
        return;
      }

      if (profilError) {
        router.replace("/cont");
        return;
      }

      if (!profil?.nume) {
        router.replace("/date-personale");
        return;
      }

      if (!profil.profil_bac) {
        router.replace("/profil");
        return;
      }

      if (!profil.evaluare_initiala_finalizata) {
        router.replace("/evaluare");
        return;
      }

      localStorage.setItem(
        "bac-mate-nume",
        profil.nume
      );

      localStorage.setItem(
        "bac-mate-profil-cod",
        profil.profil_bac
      );

      localStorage.setItem(
        "bac-mate-evaluare-initiala-finalizata",
        "da"
      );

      const finalizataLocal =
        localStorage.getItem(
          lectie.storageKeyFinalizata
        ) === "da";

      const xpLocal = Number(
        localStorage.getItem(
          lectie.storageKeyXp
        ) || "0"
      );

      if (activ) {
        setLectieFinalizata(finalizataLocal);

        setXpLectie(
          Number.isNaN(xpLocal) ? 0 : xpLocal
        );
      }

      const { data, error } = await supabase
        .from("student_progress")
        .select("completed, xp")
        .eq("user_id", user.id)
        .eq("lesson_id", lectie.id)
        .maybeSingle();

      if (!activ) {
        return;
      }

      if (!error && data) {
        const xpSupabase =
          typeof data.xp === "number"
            ? data.xp
            : 0;

        const finalizataSupabase =
          data.completed === true;

        setXpLectie(xpSupabase);

        setLectieFinalizata(
          finalizataSupabase
        );

        localStorage.setItem(
          lectie.storageKeyXp,
          String(xpSupabase)
        );

        if (finalizataSupabase) {
          localStorage.setItem(
            lectie.storageKeyFinalizata,
            "da"
          );
        } else {
          localStorage.removeItem(
            lectie.storageKeyFinalizata
          );
        }
      }

      if (activ) {
        setAccesVerificat(true);
      }
    }

    verificaAccesulSiIncarcaProgresul();

    return () => {
      activ = false;
    };
  }, [
    lectie.id,
    lectie.storageKeyFinalizata,
    lectie.storageKeyXp,
    router,
    supabase,
  ]);

  const exercitiu =
    lectie.exercitii[exercitiuCurent];

  const esteUltimul =
    exercitiuCurent ===
    lectie.exercitii.length - 1;

  const corect =
    raspuns === exercitiu?.corect;

  const xpMaxim =
    lectie.exercitii.length * 10;

  async function salveazaProgresulInSupabase(
    xp: number,
    finalizata: boolean
  ) {
    setSalvareCloud("salvare");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      setSalvareCloud("eroare");
      router.replace("/cont");
      return;
    }

    const { error } = await supabase
      .from("student_progress")
      .upsert(
        {
          user_id: user.id,
          lesson_id: lectie.id,
          xp,
          completed: finalizata,
          updated_at: new Date().toISOString(),
        },
        {
          onConflict: "user_id,lesson_id",
        }
      );

    if (error) {
      console.error(
        "Eroare la salvarea progresului:",
        error
      );

      setSalvareCloud("eroare");
      return;
    }

    setSalvareCloud("salvat");
  }

  async function verificaRaspunsul() {
    if (
      raspuns === null ||
      !exercitiu ||
      verificat
    ) {
      return;
    }

    setVerificat(true);

    if (raspuns === exercitiu.corect) {
      const xpNou = Math.min(
        xpLectie + 10,
        xpMaxim
      );

      const finalizataAcum =
        esteUltimul;

      setXpLectie(xpNou);

      localStorage.setItem(
        lectie.storageKeyXp,
        String(xpNou)
      );

      if (finalizataAcum) {
        setLectieFinalizata(true);

        localStorage.setItem(
          lectie.storageKeyFinalizata,
          "da"
        );
      }

      await salveazaProgresulInSupabase(
        xpNou,
        finalizataAcum ||
          lectieFinalizata
      );
    }
  }

  function urmatorulExercitiu() {
    if (
      exercitiuCurent >=
      lectie.exercitii.length - 1
    ) {
      return;
    }

    setExercitiuCurent(
      (valoare) => valoare + 1
    );

    setRaspuns(null);
    setVerificat(false);
    setSalvareCloud("nimic");
  }

  function incearcaDinNou() {
    setRaspuns(null);
    setVerificat(false);
    setSalvareCloud("nimic");
  }

  if (!accesVerificat) {
    return (
      <main className="min-h-screen bg-slate-950 text-white">
        <div className="mx-auto max-w-5xl px-6 py-20">
          <p className="text-slate-400">
            Se verifică autentificarea și se încarcă
            lecția...
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 text-white">
      <header className="border-b border-slate-800">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-5">
          <a
            href="/programa"
            className="font-bold text-slate-300 transition hover:text-white"
          >
            ← Programa mea
          </a>

          <a
            href="/"
            className="text-xl font-black"
          >
            BAC{" "}
            <span className="text-blue-500">
              MATE
            </span>
          </a>

          <div className="rounded-xl bg-blue-500/10 px-4 py-2 text-sm font-bold text-blue-400">
            {lectie.profil}
          </div>
        </div>
      </header>

      <div className="mx-auto max-w-5xl px-6 py-10">
        <section>
          <div className="flex flex-wrap items-center gap-3">
            <span className="rounded-full bg-blue-500/10 px-3 py-1 text-sm font-bold text-blue-400">
              MODUL {lectie.modul}
            </span>

            <span className="rounded-full bg-slate-900 px-3 py-1 text-sm font-bold text-slate-400">
              Lecția {lectie.numarLectie}
            </span>

            <span className="rounded-full bg-slate-900 px-3 py-1 text-sm font-bold text-slate-400">
              {lectie.clasa}
            </span>
          </div>

          <h1 className="mt-5 text-4xl font-black leading-tight md:text-5xl">
            {lectie.titlu}
          </h1>

          <p className="mt-5 max-w-3xl text-lg leading-8 text-slate-300">
            {lectie.descriere}
          </p>

          <div className="mt-8 h-3 overflow-hidden rounded-full bg-slate-800">
            <div
              className="h-full rounded-full bg-blue-500"
              style={{
                width: `${
                  (lectie.numarLectie /
                    lectie.totalLectiiModul) *
                  100
                }%`,
              }}
            />
          </div>

          <p className="mt-2 text-sm text-slate-500">
            Modul {lectie.modul} • Lecția{" "}
            {lectie.numarLectie} din{" "}
            {lectie.totalLectiiModul}
          </p>
        </section>

        <section className="mt-10 rounded-3xl border border-blue-500/20 bg-blue-500/5 p-7">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            🎯 Obiective
          </p>

          <h2 className="mt-3 text-2xl font-black">
            Ce vei ști să faci după această
            lecție
          </h2>

          <div className="mt-6 grid gap-4 md:grid-cols-3">
            {lectie.obiective.map(
              (obiectiv, index) => (
                <div
                  key={`${obiectiv.titlu}-${index}`}
                  className="rounded-2xl bg-slate-950 p-5"
                >
                  <p className="text-3xl">
                    {obiectiv.icon}
                  </p>

                  <p className="mt-3 font-black">
                    {obiectiv.titlu}
                  </p>

                  <p className="mt-2 text-sm leading-6 text-slate-400">
                    {obiectiv.descriere}
                  </p>
                </div>
              )
            )}
          </div>
        </section>

        <section className="mt-10">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Lecția video
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Învață pas cu pas
          </h2>

          <p className="mt-3 text-slate-400">
            Videoclipurile BAC MATE vor fi
            integrate aici.
          </p>

          <div className="mt-7 space-y-6">
            {lectie.videoLectii.map(
              (video) => {
                const deschis =
                  videoDeschis === video.numar;

                return (
                  <article
                    key={video.numar}
                    className="overflow-hidden rounded-3xl border border-slate-800 bg-slate-900"
                  >
                    <div className="relative flex min-h-[300px] items-center justify-center bg-slate-950 px-6 py-10">
                      <div className="absolute left-5 top-5 rounded-full bg-blue-600 px-4 py-2 text-sm font-black">
                        VIDEO {video.numar}
                      </div>

                      <div className="absolute right-5 top-5 rounded-full bg-slate-900 px-4 py-2 text-sm text-slate-300">
                        ⏱ {video.durata}
                      </div>

                      <div className="max-w-xl text-center">
                        <button
                          type="button"
                          onClick={() =>
                            setVideoDeschis(
                              deschis
                                ? null
                                : video.numar
                            )
                          }
                          className="mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-blue-600 text-3xl shadow-lg transition hover:scale-105 hover:bg-blue-500"
                        >
                          ▶
                        </button>

                        <h3 className="mt-6 text-2xl font-black md:text-3xl">
                          {video.titlu}
                        </h3>

                        <p className="mt-3 leading-7 text-slate-400">
                          {video.descriere}
                        </p>

                        <p className="mt-5 text-sm font-bold text-slate-600">
                          Videoclipul BAC MATE va fi
                          integrat aici.
                        </p>
                      </div>
                    </div>

                    <div className="p-6 md:p-7">
                      <button
                        type="button"
                        onClick={() =>
                          setVideoDeschis(
                            deschis
                              ? null
                              : video.numar
                          )
                        }
                        className="flex w-full items-center justify-between text-left"
                      >
                        <div>
                          <p className="text-sm font-black uppercase tracking-wider text-emerald-400">
                            După video
                          </p>

                          <p className="mt-1 text-xl font-black">
                            Ce trebuie să reții
                          </p>
                        </div>

                        <span className="text-2xl text-slate-400">
                          {deschis ? "−" : "+"}
                        </span>
                      </button>

                      {deschis && (
                        <div className="mt-6">
                          <div className="grid gap-3 md:grid-cols-2">
                            {video.idei.map(
                              (idee, index) => (
                                <div
                                  key={`${idee}-${index}`}
                                  className="flex gap-3 rounded-2xl bg-slate-950 p-4"
                                >
                                  <span className="text-emerald-400">
                                    ✓
                                  </span>

                                  <p className="font-semibold text-slate-200">
                                    {idee}
                                  </p>
                                </div>
                              )
                            )}
                          </div>

                          <div className="mt-5 rounded-2xl border border-blue-500/20 bg-blue-500/5 p-5">
                            <p className="font-black text-blue-400">
                              {video.exempluTitlu}
                            </p>

                            <p className="mt-3 leading-7 text-slate-300">
                              {video.exemplu}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </article>
                );
              }
            )}
          </div>
        </section>

        <section className="mt-10 rounded-3xl border border-emerald-500/20 bg-emerald-500/5 p-7">
          <p className="text-sm font-black uppercase tracking-wider text-emerald-400">
            🧠 Fișa de 30 de secunde
          </p>

          <h2 className="mt-3 text-2xl font-black">
            {lectie.fisaRapida.titlu}
          </h2>

          <div className="mt-6 space-y-3">
            {lectie.fisaRapida.continut.map(
              (rand, index) => (
                <div
                  key={`${rand}-${index}`}
                  className="flex gap-3 rounded-2xl bg-slate-950 p-4"
                >
                  <span className="text-emerald-400">
                    ✓
                  </span>

                  <p className="leading-7 text-slate-300">
                    {rand}
                  </p>
                </div>
              )
            )}
          </div>
        </section>

        <section className="mt-8 rounded-3xl border border-violet-500/30 bg-violet-500/10 p-7">
          <p className="text-sm font-black uppercase tracking-wider text-violet-400">
            🤖 Profesorul BAC MATE
          </p>

          <h2 className="mt-3 text-2xl font-black">
            Ai nevoie de ajutor?
          </h2>

          <p className="mt-3 leading-7 text-slate-300">
            Profesorul AI va putea să îți explice
            această lecție în alt mod, să îți ofere
            exemple și să identifice exact unde te-ai
            blocat.
          </p>

          <div className="mt-5 flex flex-wrap gap-3">
            <button
              type="button"
              className="rounded-xl bg-violet-600 px-4 py-3 font-bold transition hover:bg-violet-500"
            >
              💡 Explică-mi mai simplu
            </button>

            <button
              type="button"
              className="rounded-xl border border-violet-500/30 px-4 py-3 font-bold"
            >
              🧩 Dă-mi un exemplu
            </button>

            <button
              type="button"
              className="rounded-xl border border-violet-500/30 px-4 py-3 font-bold"
            >
              🎯 Testează-mă
            </button>
          </div>

          <p className="mt-4 text-xs text-violet-300/60">
            Profesorul AI va fi conectat într-o etapă
            ulterioară.
          </p>
        </section>

        {exercitiu && (
          <section className="mt-10 rounded-3xl border border-slate-800 bg-slate-900 p-7 md:p-8">
            <div className="flex flex-wrap items-center justify-between gap-4">
              <div>
                <p className="text-sm font-black uppercase tracking-wider text-blue-400">
                  Mini-test
                </p>

                <h2 className="mt-2 text-3xl font-black">
                  Verifică dacă ai înțeles
                </h2>

                <p className="mt-2 text-slate-400">
                  {lectie.exercitii.length} întrebări •
                  maximum {xpMaxim} XP
                </p>
              </div>

              <div className="rounded-xl bg-slate-950 px-4 py-3 font-black">
                {exercitiuCurent + 1}/
                {lectie.exercitii.length}
              </div>
            </div>

            <div className="mt-6 h-2 overflow-hidden rounded-full bg-slate-800">
              <div
                className="h-full rounded-full bg-blue-500 transition-all"
                style={{
                  width: `${
                    ((exercitiuCurent + 1) /
                      lectie.exercitii.length) *
                    100
                  }%`,
                }}
              />
            </div>

            <h3 className="mt-8 text-xl font-black md:text-2xl">
              {exercitiu.intrebare}
            </h3>

            <div className="mt-6 grid gap-3">
              {exercitiu.variante.map(
                (varianta, index) => {
                  let stil =
                    "border-slate-700 bg-slate-950 hover:border-slate-500";

                  if (raspuns === index) {
                    stil =
                      "border-blue-500 bg-blue-500/10";
                  }

                  if (
                    verificat &&
                    index === exercitiu.corect
                  ) {
                    stil =
                      "border-emerald-500 bg-emerald-500/10";
                  }

                  if (
                    verificat &&
                    raspuns === index &&
                    index !== exercitiu.corect
                  ) {
                    stil =
                      "border-red-500 bg-red-500/10";
                  }

                  return (
                    <button
                      key={`${varianta}-${index}`}
                      type="button"
                      disabled={verificat}
                      onClick={() =>
                        setRaspuns(index)
                      }
                      className={`rounded-2xl border px-5 py-4 text-left font-semibold transition ${stil}`}
                    >
                      <span className="mr-3 text-slate-500">
                        {String.fromCharCode(
                          65 + index
                        )}
                        .
                      </span>

                      {varianta}
                    </button>
                  );
                }
              )}
            </div>

            {!verificat && (
              <button
                type="button"
                onClick={verificaRaspunsul}
                disabled={raspuns === null}
                className={`mt-6 rounded-xl px-6 py-3 font-black transition ${
                  raspuns !== null
                    ? "bg-blue-600 hover:bg-blue-500"
                    : "cursor-not-allowed bg-slate-800 text-slate-500"
                }`}
              >
                Verifică răspunsul
              </button>
            )}

            {verificat && (
              <div
                className={`mt-6 rounded-2xl p-6 ${
                  corect
                    ? "bg-emerald-500/10"
                    : "bg-red-500/10"
                }`}
              >
                <p
                  className={`text-lg font-black ${
                    corect
                      ? "text-emerald-400"
                      : "text-red-400"
                  }`}
                >
                  {corect
                    ? "✓ Corect! Ai câștigat 10 XP."
                    : "Nu este răspunsul corect."}
                </p>

                <p className="mt-3 leading-7 text-slate-300">
                  {exercitiu.explicatie}
                </p>

                {corect &&
                  salvareCloud === "salvare" && (
                    <p className="mt-3 text-sm font-bold text-blue-400">
                      ☁️ Se salvează progresul...
                    </p>
                  )}

                {corect &&
                  salvareCloud === "salvat" && (
                    <p className="mt-3 text-sm font-bold text-emerald-400">
                      ✓ Progres salvat în cont
                    </p>
                  )}

                {corect &&
                  salvareCloud === "eroare" && (
                    <p className="mt-3 text-sm font-bold text-amber-400">
                      ⚠️ Progresul este păstrat pe acest
                      dispozitiv, dar nu a putut fi
                      salvat momentan în cont.
                    </p>
                  )}

                {corect && !esteUltimul && (
                  <button
                    type="button"
                    onClick={urmatorulExercitiu}
                    className="mt-5 rounded-xl bg-blue-600 px-5 py-3 font-black hover:bg-blue-500"
                  >
                    Următorul exercițiu →
                  </button>
                )}

                {!corect && (
                  <button
                    type="button"
                    onClick={incearcaDinNou}
                    className="mt-5 rounded-xl border border-slate-700 px-5 py-3 font-black hover:bg-slate-950"
                  >
                    Încearcă din nou
                  </button>
                )}

                {corect &&
                  esteUltimul &&
                  lectieFinalizata && (
                    <div className="mt-6 rounded-2xl bg-slate-950 p-6">
                      <p className="text-2xl font-black">
                        🎉 Lecție finalizată
                      </p>

                      <p className="mt-3 text-slate-300">
                        Ai terminat lecția și ai
                        acumulat{" "}
                        <strong>
                          {xpLectie} XP
                        </strong>
                        .
                      </p>

                      <div className="mt-5 flex flex-col gap-3 sm:flex-row">
                        <a
                          href="/programa"
                          className="rounded-xl bg-blue-600 px-5 py-3 text-center font-black hover:bg-blue-500"
                        >
                          Continuă traseul →
                        </a>

                        <a
                          href="/dashboard"
                          className="rounded-xl border border-slate-700 px-5 py-3 text-center font-black hover:bg-slate-900"
                        >
                          Dashboard
                        </a>
                      </div>
                    </div>
                  )}
              </div>
            )}

            <div className="mt-6 flex items-center justify-between border-t border-slate-800 pt-5">
              <span className="text-sm text-slate-500">
                XP în această lecție
              </span>

              <span className="font-black text-amber-400">
                ⭐ {xpLectie} XP
              </span>
            </div>
          </section>
        )}

        {lectie.urmatoareaLectie && (
          <section className="mt-8 rounded-3xl border border-slate-800 bg-slate-900 p-7">
            <p className="text-sm font-black uppercase tracking-wider text-slate-500">
              Următoarea lecție
            </p>

            <h2 className="mt-2 text-xl font-black">
              {lectie.urmatoareaLectie.titlu}
            </h2>

            {lectie.urmatoareaLectie.href &&
            lectieFinalizata ? (
              <a
                href={lectie.urmatoareaLectie.href}
                className="mt-5 inline-block rounded-xl bg-blue-600 px-5 py-3 font-black transition hover:bg-blue-500"
              >
                Continuă →
              </a>
            ) : (
              <p className="mt-4 text-sm font-bold text-slate-600">
                🔒 Finalizează această lecție pentru a
                continua
              </p>
            )}
          </section>
        )}
      </div>
    </main>
  );
}